<script setup>
import { computed,onMounted,ref } from 'vue';import { api } from '../api.js';import { useActivitiesStore } from '../stores/activities.js';import { apiErrorMessage,useNotificationsStore } from '../stores/notifications.js'
const props=defineProps({activityId:{type:Number,required:true}});const activities=useActivitiesStore();const notifications=useNotificationsStore();const catalog=ref([]);const selectedId=ref('');const price=ref(0);const quantity=ref(1);const busy=ref(false);const error=ref('');const selected=computed(()=>catalog.value.find(item=>item.id===Number(selectedId.value)))
onMounted(async()=>{try{catalog.value=(await api.get('/api/loot-catalog')).data}catch(e){error.value='Не удалось загрузить справочник лута.'}})
async function submit(){busy.value=true;error.value='';try{await activities.addLoot(props.activityId,{loot_catalog_item_id:selectedId.value,unit_price:price.value,quantity:quantity.value});notifications.success('Лут добавлен в активность.');selectedId.value='';price.value=0;quantity.value=1}catch(e){error.value=apiErrorMessage(e,'Не удалось добавить лут.');notifications.error(error.value)}finally{busy.value=false}}
</script>
<template><div class="panel manual-loot"><div class="panel-title"><div><h2>Добавить лут</h2><p class="muted">Выберите предмет из справочника и укажите цену</p></div><RouterLink class="catalog-link" to="/admin">Справочник лута</RouterLink></div><form class="catalog-loot-form" @submit.prevent="submit"><label>Предмет<div class="catalog-select-wrap"><img v-if="selected?.icon_url" :src="selected.icon_url"><select v-model="selectedId" required><option value="" disabled>Выберите предмет</option><option v-for="item in catalog" :key="item.id" :value="item.id">{{ item.name }}</option></select></div></label><label>Цена за единицу, золото<input v-model.number="price" required type="number" min="0" step="1"></label><label>Количество<input v-model.number="quantity" required type="number" min="1" step="1"></label><button class="primary" :disabled="busy||!selectedId">{{ busy?'Добавление…':'Добавить лут' }}</button></form><p v-if="!catalog.length&&!error" class="empty">Справочник пуст. Сначала добавьте предметы в разделе администрирования.</p><p v-if="error" class="notice error">{{ error }}</p></div></template>
